    "notation_alert": "تشترط د. رويدا أن تكون الأبجدية Σ منتهية وغير فارغة (Finite & Non-empty). إذا كان طول السلسلة n، فإن عدد البوادئ الممكنة هو n+1 باحتساب ε.",
