    "exam_trap": "في DFA يجب أن يكون لكل حالة سهم خارج لكل رمز من Σ! إذا انكسر الشرط (مثل نمط يبدأ بـ 'ab' ثم أتى 'b') يجب توجيه السهم إلى حالة مصيدة (Dead State) لا خروج منها. ترك سهم مفقود يخصم درجات فوراً في اختبار د. رويدا.",
    "notation_alert": "بمجرد دخول الآلة في حالة المصيدة (Dead State)، فإنها لا تغادرها أبداً: δ(q_dead, a) = q_dead لكل a ∈ Σ.",
