    "title_en": "Transition Tables, State Diagrams & Extended Transition Function delta*",
    "exam_trap": "في جدول الانتقالات، تُشار حالة البداية بسهم ->، وتُشار الحالات النهائية بنجمة * أو دائرة. احذر نسيان وضع النجمة على الحالات المقبولة في جدول الاختبار.",
    "notation_alert": "التعريف الاستقرائي للدالة الموسعة: δ*(q, ε) = q و δ*(q, xa) = δ(δ*(q, x), a). في الـ DFA تُرجع الدالة حالة واحدة مفردة حتماً: δ*(q, w) ∈ Q.",
