  "L4-S001": {
    "concept_id": "c_l4_regex_patterns",
    "title_ar": "التعابير النمطية والمتطابقات الجبرية (RegEx Formal Definition & Identities)",
    "title_en": "Regular Expressions Syntax, Operators Precedence & Algebraic Identities",
    "exam_trap": "أولوية العمليات في التعابير المنتظمة: 1) نجمة كلين * (الأعلى)، 2) الدمج Concatenation، 3) الاتحاد Union (+) (الأدنى). لذا فإن ab* تعني a متبوعة بعدد اختياري من b، وليست (ab)*!",
    "notation_alert": "رمز + في التعابير النمطية يعني الاتحاد Union (أو الاختيار Or)، ويُكتب في بعض المراجع الأخرى برمز | (Pipe). د. رويدا تستخدم + في سلايداتها.",
    "en_url": "https://www.youtube.com/watch?v=FOhEmW_nMRs&t=20s",
    "en_label": "Neso Academy (00:20)",
    "ar_url": "https://www.youtube.com/watch?v=1BClOOW4sEM&t=30s",
    "ar_label": "AbuFatimah Alali (00:30)"
  },
