    "title_en": "Right-Linear, Left-Linear, Regular Grammars & CFG Ambiguity",
    "exam_trap": "ممنوع قطعاً الخلط بين القواعد الخطية اليمنى واليسرى في نفس المجموعة! إذا احتوت القواعد على A -> aB و C -> Dd معاً، تصبح خطية عامة (Linear Grammar) وليست منتظمة (Regular Grammar)!",
    "notation_alert": "القواعد الخطية اليمنى والخطية اليسرى تولد كلاهما لغات منتظمة، لكن الخلط بينهما قد يولد لغات غير منتظمة مثل {a^n b^n}.",
