    "title_en": "CFG Simplification (Null, Unit, Useless) & Chomsky Normal Form (CNF)",
    "exam_trap": "ترتيب تبسيط القواعد CFG إلزامي وحاسم: 1) إزالة قواعد إبسلون (Null Productions)، 2) إزالة القواعد الأحادية (Unit Productions)، 3) إزالة الرموز غير المفيدة (Useless Symbols). أي إخلال بهذا الترتيب يعيد الرموز المحذوفة!",
    "notation_alert": "في صيغة تشومسكي الطبيعية CNF، إذا كانت السلسلة المشتقة طولها n (حيث n >= 1)، فإن عدد خطوات الاشتقاق اللازمة هو 2n - 1 خطوة بالضبط.",
